begin;
create table if not exists public.housekeeping_indents(
 id uuid primary key, indent_no bigint generated by default as identity unique,
 store_item_id uuid not null references public.consumable_store_items(id),item_name text not null,unit text not null,
 requested_qty numeric(12,2) not null check(requested_qty>0),purpose text not null,
 status text not null default 'Initiated' check(status in ('Initiated','Approved','Rejected','Handed Over','Received')),
 requested_by uuid not null references public.profiles(id),requested_by_name text not null,requested_at timestamptz not null default now(),
 approved_qty numeric(12,2),approved_by uuid references public.profiles(id),approved_by_name text,approved_at timestamptz,approval_remarks text,
 handed_over_qty numeric(12,2),handed_over_by uuid references public.profiles(id),handed_over_by_name text,handed_over_at timestamptz,handover_remarks text,
 received_qty numeric(12,2),received_by uuid references public.profiles(id),received_by_name text,received_at timestamptz,receipt_remarks text
);
create table if not exists public.housekeeping_item_usage(
 id uuid primary key,indent_id uuid not null references public.housekeeping_indents(id),
 quantity numeric(12,2) not null check(quantity>0),used_on date not null,remarks text not null,
 recorded_by uuid not null references public.profiles(id),recorded_by_name text not null,recorded_at timestamptz not null default now(),
 voided_at timestamptz,voided_by uuid references public.profiles(id),voided_by_name text,void_reason text
);
create index if not exists housekeeping_usage_indent_idx on public.housekeeping_item_usage(indent_id);
create or replace function public.housekeeping_permissions() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare a record; active boolean; nm boolean; controller boolean;
begin
 select * into a from public.stores_actor();
 select coalesce(p.is_active,true) into active from public.profiles p where p.id=a.actor_id;
 if a.actor_id is null or active is not true then return '{}'::jsonb; end if;
 nm:=lower(trim(regexp_replace(coalesce(a.actor_designation,''),'[._-]+',' ','g'))) in ('nurse manager','nursing manager') or (nullif(trim(a.actor_designation),'') is null and a.actor_role='Manager' and exists(select 1 from public.profiles p where p.id=a.actor_id and lower(trim(p.department))='nursing'));
 controller:=public.stores_controller_authorised();
 return jsonb_build_object('request',a.actor_role='STD','approve',coalesce(nm,false),'handover',controller,'receive',a.actor_role='STD','use',a.actor_role='STD','read',a.actor_role in ('STD','Admin','Manager','Accounts') or coalesce(nm,false) or controller);
end $$;
alter table public.housekeeping_indents enable row level security;
alter table public.housekeeping_item_usage enable row level security;
revoke all on public.housekeeping_indents,public.housekeeping_item_usage from anon,authenticated;
grant select on public.housekeeping_indents,public.housekeeping_item_usage to authenticated;
drop policy if exists housekeeping_indents_read on public.housekeeping_indents;
create policy housekeeping_indents_read on public.housekeeping_indents for select to authenticated using ((public.housekeeping_permissions()->>'read')::boolean is true);
drop policy if exists housekeeping_usage_read on public.housekeeping_item_usage;
create policy housekeeping_usage_read on public.housekeeping_item_usage for select to authenticated using ((public.housekeeping_permissions()->>'read')::boolean is true);
revoke all on function public.housekeeping_permissions() from public,anon;
grant execute on function public.housekeeping_permissions() to authenticated;
create or replace function public.housekeeping_workflow(p_action text,p_data jsonb default '{}') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare a record; rights jsonb; v public.housekeeping_indents%rowtype; item public.consumable_store_items%rowtype; entry public.housekeeping_item_usage%rowtype; key uuid; qty numeric; day date; used numeric; stock numeric; note text; result jsonb;
begin
 select * into a from public.stores_actor(); rights:=public.housekeeping_permissions();
 if (rights->>'read')::boolean is not true then raise exception 'Housekeeping access is not available for this account.'; end if;
 if p_action='load' then return jsonb_build_object('permissions',rights,'indents',coalesce((select jsonb_agg(to_jsonb(i) order by i.requested_at desc) from public.housekeeping_indents i),'[]'::jsonb),'usage',coalesce((select jsonb_agg(to_jsonb(u) order by u.used_on desc,u.recorded_at desc) from public.housekeeping_item_usage u),'[]'::jsonb),'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('balance_qty',coalesce(s.balance_qty,0)) order by i.item_name) from public.consumable_store_items i left join public.consumable_store_stock s on s.item_id=i.id where i.item_category='Housekeeping & General'),'[]'::jsonb)); end if;
 key:=(p_data->>'id')::uuid;note:=nullif(trim(p_data->>'remarks'),'');
 if p_action='request' then
  if (rights->>'request')::boolean is not true then raise exception 'Only STD Housekeeping In-charge can request items.'; end if;
  qty:=(p_data->>'quantity')::numeric;
  if key is null or qty is null or qty<=0 or qty<>round(qty,2) or qty::text in ('NaN','Infinity','-Infinity') or note is null then raise exception 'Enter the item, positive quantity (up to two decimals) and purpose.'; end if;
  select * into item from public.consumable_store_items where id=(p_data->>'item_id')::uuid;
  if not found or item.item_category<>'Housekeeping & General' or not item.active then raise exception 'Select an active Housekeeping & General item.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(key::text,0));
  select * into v from public.housekeeping_indents where id=key;
  if found then if v.requested_by=a.actor_id and v.store_item_id=item.id and v.requested_qty=qty and v.purpose=note then return jsonb_build_object('success',true,'already_saved',true); end if; raise exception 'Request reference already used.'; end if;
  insert into public.housekeeping_indents(id,store_item_id,item_name,unit,requested_qty,purpose,requested_by,requested_by_name) values(key,item.id,item.item_name,item.unit,qty,note,a.actor_id,a.actor_name);
 elsif p_action in ('approve','reject','handover','receive') then
  select * into v from public.housekeeping_indents where id=key for update;
  if not found then raise exception 'Housekeeping indent not found.'; end if;
  if p_action in ('approve','reject') then
   if (rights->>'approve')::boolean is not true then raise exception 'Only the Nursing Manager can approve or reject Housekeeping requests.'; end if;
   if v.status<>'Initiated' then raise exception 'This request has already been decided.'; end if;
   qty:=case when p_action='reject' then 0 else (p_data->>'quantity')::numeric end;
   if qty is null or (p_action='approve' and (qty<=0 or qty>v.requested_qty)) or qty<>round(qty,2) or qty::text in ('NaN','Infinity','-Infinity') then raise exception 'Approved quantity must be positive and no greater than requested.'; end if;
   if p_action='reject' and note is null then raise exception 'Rejection reason is required.'; end if;
   update public.housekeeping_indents set status=case when p_action='reject' then 'Rejected' else 'Approved' end,approved_qty=qty,approved_by=a.actor_id,approved_by_name=a.actor_name,approved_at=now(),approval_remarks=note where id=v.id;
  elsif p_action='handover' then
   if (rights->>'handover')::boolean is not true then raise exception 'Only the currently assigned Stores In-charge can hand over items.'; end if;
   if v.status<>'Approved' then raise exception 'Nursing Manager approval is required before handover; this indent may already have been handed over.'; end if;
   qty:=(p_data->>'quantity')::numeric;
   if qty is null or qty<=0 or qty>v.approved_qty or qty<>round(qty,2) or qty::text in ('NaN','Infinity','-Infinity') then raise exception 'Handover quantity must be positive and no greater than approved.'; end if;
   perform 1 from public.consumable_store_items where id=v.store_item_id for update;
   select balance_qty into stock from public.consumable_store_stock where item_id=v.store_item_id;
   if coalesce(stock,0)<qty then raise exception 'Insufficient Stores stock (available % %).',coalesce(stock,0),v.unit; end if;
   insert into public.consumable_store_ledger(item_id,movement_type,qty_in,qty_out,balance_after,reference_id,reference_text,remarks,actor_id,actor_name)
   values(v.store_item_id,'Department Issue',0,qty,stock-qty,v.id,'Housekeeping · HK-'||lpad(v.indent_no::text,5,'0'),note,a.actor_id,a.actor_name);
   update public.housekeeping_indents set status='Handed Over',handed_over_qty=qty,handed_over_by=a.actor_id,handed_over_by_name=a.actor_name,handed_over_at=now(),handover_remarks=note where id=v.id;
  else
   if (rights->>'receive')::boolean is not true then raise exception 'Only STD Housekeeping In-charge can confirm receipt.'; end if;
   if v.status<>'Handed Over' then raise exception 'Only a handed-over indent can be received.'; end if;
   qty:=(p_data->>'quantity')::numeric;
   if qty is distinct from v.handed_over_qty then raise exception 'Confirm the full handed-over quantity. If the physical quantity differs, resolve it with Stores before confirming receipt.'; end if;
   update public.housekeeping_indents set status='Received',received_qty=qty,received_by=a.actor_id,received_by_name=a.actor_name,received_at=now(),receipt_remarks=note where id=v.id;
  end if;
 elsif p_action in ('use','void_use') then
  if (rights->>'use')::boolean is not true then raise exception 'Only STD Housekeeping In-charge can record or correct usage.'; end if;
  if p_action='void_use' then
   select * into entry from public.housekeeping_item_usage where id=key;
   if not found or note is null then raise exception 'Select a usage entry and enter the correction reason.'; end if;
   perform 1 from public.housekeeping_indents where id=entry.indent_id for update;
   select * into entry from public.housekeeping_item_usage where id=key for update;
   if entry.voided_at is not null then return jsonb_build_object('success',true,'already_voided',true); end if;
   update public.housekeeping_item_usage set voided_at=now(),voided_by=a.actor_id,voided_by_name=a.actor_name,void_reason=note where id=key;
  else
   select * into v from public.housekeeping_indents where id=(p_data->>'indent_id')::uuid for update;
   if not found or v.status<>'Received' then raise exception 'STD must confirm receipt before recording usage.'; end if;
   qty:=(p_data->>'quantity')::numeric;day:=(p_data->>'used_on')::date;
   if key is null or qty is null or qty<=0 or qty<>round(qty,2) or qty::text in ('NaN','Infinity','-Infinity') or note is null then raise exception 'Enter a positive used quantity and purpose / area.'; end if;
   select * into entry from public.housekeeping_item_usage where id=key;
   if found then if entry.indent_id=v.id and entry.quantity=qty and entry.used_on=day and entry.remarks=note and entry.recorded_by=a.actor_id then return jsonb_build_object('success',true,'already_saved',true); end if;raise exception 'Usage reference already used.'; end if;
   if day is null or day<(v.received_at at time zone 'Asia/Kolkata')::date or day>(now() at time zone 'Asia/Kolkata')::date then raise exception 'Usage date must be between receipt day and today.'; end if;
   select coalesce(sum(quantity),0) into used from public.housekeeping_item_usage where indent_id=v.id and voided_at is null;
   if qty>v.received_qty-used then raise exception 'Only % % remains with Housekeeping.',v.received_qty-used,v.unit; end if;
   insert into public.housekeeping_item_usage(id,indent_id,quantity,used_on,remarks,recorded_by,recorded_by_name) values(key,v.id,qty,day,note,a.actor_id,a.actor_name);
  end if;
 else raise exception 'Unknown Housekeeping action.';
 end if;
 perform public.record_audit_event('Housekeeping '||p_action,'Housekeeping & General',key::text,p_data,'Success');
 return jsonb_build_object('success',true,'id',key);
end $$;
revoke all on function public.housekeeping_workflow(text,jsonb) from public,anon;
grant execute on function public.housekeeping_workflow(text,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
